macro_rules! test_single_key_bit_flip {
    () => {
        fn test_single_key_bit_flip < T : Hasher > (constructor : impl Fn (u128 , u128) -> T) { for bit in 0 .. 128 { let mut a = constructor (0 , 0) ; let mut b = constructor (0 , 1 << bit) ; let mut c = constructor (1 << bit , 0) ; "1234" . hash (& mut a) ; "1234" . hash (& mut b) ; "1234" . hash (& mut c) ; assert_sufficiently_different (a . finish () , b . finish () , 2) ; assert_sufficiently_different (a . finish () , c . finish () , 2) ; assert_sufficiently_different (b . finish () , c . finish () , 2) ; let mut a = constructor (0 , 0) ; let mut b = constructor (0 , 1 << bit) ; let mut c = constructor (1 << bit , 0) ; "12345678" . hash (& mut a) ; "12345678" . hash (& mut b) ; "12345678" . hash (& mut c) ; assert_sufficiently_different (a . finish () , b . finish () , 2) ; assert_sufficiently_different (a . finish () , c . finish () , 2) ; assert_sufficiently_different (b . finish () , c . finish () , 2) ; let mut a = constructor (0 , 0) ; let mut b = constructor (0 , 1 << bit) ; let mut c = constructor (1 << bit , 0) ; "1234567812345678" . hash (& mut a) ; "1234567812345678" . hash (& mut b) ; "1234567812345678" . hash (& mut c) ; assert_sufficiently_different (a . finish () , b . finish () , 2) ; assert_sufficiently_different (a . finish () , c . finish () , 2) ; assert_sufficiently_different (b . finish () , c . finish () , 2) ; } }
    };
}

test_single_key_bit_flip!();